    /// Paid in full, sold at half: never a gain.
    #[test]
    fn market_attach_price_standard_sold_back_loses_half() {
        assert_eq!(market_attach_round_trip("attach-standard-sold", 300_000, PriceMode::Standard), 300_000 - 231_500 + 115_750);
    }

