        let held = serde_json::to_value(list_held_equipment_at_root(&root).unwrap()).unwrap();
        assert!(held.as_array().unwrap().iter().all(|copy| copy.get("override").is_none()), "{held}");
        std::fs::remove_dir_all(&root).ok();
